#pragma once

#include "monitors/parser/gen/LogBaseVisitor.h"

/**
 * Visitor implementation namespace (avoid name clash with autogenerated classes)
 */
namespace impl {

/**
 * Visitor for parsing Hydra2-style logs.
 */
class LogVisitor : public LogBaseVisitor {
  public:
    /**
     * Visits a log consisting of one or more log entries and builds a Trace (trace) object.
     * @param context Context.
     * @return Trace (log) object.
     */
    antlrcpp::Any visitLog(LogParser::LogContext *context) override;

    /**
     * Visits a log entry consisting of a time specification and one or more true atomics and builds a log entry.
     * @param context Context.
     * @return Private log entry struct (implementation detail).
     */
    antlrcpp::Any visitEntry(LogParser::EntryContext *context) override;

    /**
     * Visits an identifier.
     * @param context Context.
     * @return Identifier (string).
     */
    antlrcpp::Any visitIdentifier(LogParser::IdentifierContext *context) override;

    /**
     * Visits a time specification and parses it into a time index.
     * @param context Context.
     * @return Time index (size_t).
     */
    antlrcpp::Any visitTime(LogParser::TimeContext *context) override;
};

}; /* namespace impl */
